const forumTopics = `-- name: ForumTopics :many
SELECT p.uuid,p.slug,p.title,p.body,p.created_at,p.updated_at,c.slug AS category_slug,
 (SELECT count(*) FROM forum_votes v WHERE v.organization_id=p.organization_id AND v.post_id=p.id)::bigint AS votes,
 a.uuid AS accepted_reply_uuid
FROM forum_posts p JOIN forum_categories c ON c.organization_id=p.organization_id AND c.id=p.category_id
LEFT JOIN forum_posts a ON a.organization_id=p.organization_id AND a.id=p.accepted_reply_id AND a.status='published'
WHERE p.organization_id=$1 AND p.topic_id IS NULL AND p.status='published'
AND ($2::text='' OR c.slug=$2)
AND ($3::text='' OR p.title ILIKE '%'||$3||'%')
ORDER BY p.created_at DESC,p.id DESC LIMIT $5 OFFSET $4
`

type ForumTopicsParams struct {
	OrganizationID int64  `json:"organization_id"`
	Category       string `json:"category"`
	Q              string `json:"q"`
	RowOffset      int32  `json:"row_offset"`
	RowLimit       int32  `json:"row_limit"`
}

type ForumTopicsRow struct {
	Uuid              uuid.UUID          `json:"uuid"`
	Slug              string             `json:"slug"`
	Title             string             `json:"title"`
	Body              string             `json:"body"`
	CreatedAt         pgtype.Timestamptz `json:"created_at"`
	UpdatedAt         pgtype.Timestamptz `json:"updated_at"`
	CategorySlug      string             `json:"category_slug"`
	Votes             int64              `json:"votes"`
	AcceptedReplyUuid pgtype.UUID        `json:"accepted_reply_uuid"`
}

func (q *Queries) ForumTopics(ctx context.Context, arg ForumTopicsParams) ([]ForumTopicsRow, error) {
	rows, err := q.db.Query(ctx, forumTopics,
		arg.OrganizationID,
		arg.Category,
		arg.Q,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ForumTopicsRow{}
	for rows.Next() {
		var i ForumTopicsRow
		if err := rows.Scan(
			&i.Uuid,
			&i.Slug,
			&i.Title,
			&i.Body,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CategorySlug,
			&i.Votes,
			&i.AcceptedReplyUuid,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

